              + T(70, 13, 'A', ' text-anchor="middle"') + T(62, 186, 'B', ' text-anchor="middle"') + T(280, 186, 'C', ' text-anchor="middle"') + T(62, 115, 'D', ' text-anchor="end"') + T(196, 104, 'E')
