          const h1 = `Compare le déplacement de $${dep}$ à $${U}$ et celui de $${U}$ à $${E}$.`;
          const h2 = `Dans un parallélogramme, deux côtés opposés se parcourent dans le même sens : la translation qui transforme $${P}$ en $${vers}$ transforme aussi $${dep}$ en $${U}$.`;
          const sol = `**Étape 1.** $${P}${R}${U}${S}$ est un parallélogramme, donc la translation qui transforme $${P}$ en $${vers}$ transforme aussi $${dep}$ en $${U}$.\n**Étape 2.** Cette translation transforme aussi $${U}$ en $${E}$ : les déplacements de $${dep}$ à $${U}$ et de $${U}$ à $${E}$ sont les mêmes. Les points $${dep}$, $${U}$ et $${E}$ sont donc alignés dans cet ordre, avec $${dep}${U} = ${U}${E} = ${P}${vers} = ${lg}$ cm.`;
          const v = { k: '4G3.deuxTrans', ask, a, b, which, noms: { P, R, U, S, E } };
