    const pts = (L, l, h) => ({ A: [0, 0, 0], B: [L, 0, 0], C: [L, l, 0], D: [0, l, 0], E: [0, 0, h], F: [L, 0, h], G: [L, l, h], H: [0, l, h] });
    const REP = 'on prend $A$ comme origine, avec les abscisses sur $(AB)$, les ordonnées sur $(AD)$ et les altitudes sur $(AE)$';
