    const pave = (L, l, h) => `${this._h4_svgPave4G4()}Dans le pavé droit $ABCDEFGH$, ${REP}. On donne $AB = ${L}$, $AD = ${l}$ et $AE = ${h}$.`;
    const paveG = (L, l, h) => `${this._h4_svgPave4G4()}Dans le pavé droit $ABCDEFGH$, ${REP}. Le point $G$ a pour coordonnées $(${L} ; ${l} ; ${h})$.`;
    const ORDRE = 'dans l\'ordre (abscisse ; ordonnée ; altitude), séparées par des points-virgules';
