          const x = this.shuffle([2, 3, 4, 5, 6, 8, 10, 12]).slice(0, 3).sort((u, v) => u - v);
          const k = this.randInt(2, 9), b = this.randInt(1, 9), e = this.randChoice([-1, 1]);
          const j = this.randChoice([1, 2]), o = 3 - j;
          const kind = this.randChoice(['prop', 'ajout', 'rompu']);
          const y = kind === 'prop' ? x.map(v => k * v) : kind === 'ajout' ? x.map(v => v + b) : x.map((v, i) => k * v + (i === j ? e : 0));
          const good = kind === 'prop' ? TAB_OUI : kind === 'ajout' ? TAB_AJOUT : TAB_NON;
          const q0 = `\\frac{${y[0]}}{${x[0]}}`, q1 = `\\frac{${y[1]}}{${x[1]}}`, q2 = `\\frac{${y[2]}}{${x[2]}}`, qo = `\\frac{${y[o]}}{${x[o]}}`;
          const fin = kind === 'prop' ? `**Conclusion :** c'est un tableau de proportionnalité, de coefficient $${k}$.` : '**Conclusion :** ce n\'est pas un tableau de proportionnalité.';
          const sol = kind === 'prop'
            ? `Pour chaque colonne, on calcule le quotient de la deuxième ligne par la première : $${q0} = ${k}$, $${q1} = ${k}$ et $${q2} = ${k}$.\nCes quotients sont tous égaux à $${k}$ : on multiplie toujours par ce nombre.`
            : kind === 'ajout'
