  _h3a_Org1_walk(mono) {
    // Fonction affine par morceaux : nœuds (x entier de -4 à 4, y entier entre -3 et 5)
    for (;;) {
      const pts = []; let y = this.randInt(-3, 2);
      const dir = this.randChoice([1, -1]);
      if (mono && dir < 0) y = this.randInt(2, 5);
      for (let x = -4; x <= 4; x++) {
        pts.push([x, y]);
        const st = mono ? dir * this.randInt(0, 2) : this.randChoice([-2, -1, 0, 1, 2]);
        y = Math.max(-3, Math.min(5, y + st));
      }
      if (mono) {
        // strictement monotone sur chaque nœud : on ré-essaie si deux nœuds ont la même ordonnée
        const ys = pts.map(p => p[1]);
        if (new Set(ys).size === ys.length) return pts;
        continue;
      }
      const ys = pts.map(p => p[1]);
      if (Math.max(...ys) - Math.min(...ys) >= 4) return pts;
    }
  },

