      if (ty === 'losange') data = this.randChoice([`$AB = BC = ${c1}$ cm et $\\widehat{ABC} = ${this.randChoice([R(50, 80), R(100, 130)])}°$`, `ses diagonales sont perpendiculaires et $AC = ${d1}$ cm, $BD = ${d2}$ cm`]);
      if (ty === 'carré') data = this.randChoice([`$AB = BC = ${c1}$ cm et $AC = BD$`, `ses diagonales sont perpendiculaires et de même longueur`, `$\\widehat{ABC} = 90°$ et $AB = BC = ${c1}$ cm`]);
