      const p1 = 5 * R(3, 8), p2 = 5 * R(3, 8), rest = 100 - p1 - p2, juste = Math.random() < 0.35, p3 = juste ? rest : rest + 5 * R(2, 4), S = p1 + p2 + p3;
      const good = juste ? 'Aucune erreur : la somme des pourcentages vaut bien 100 %.' : `Il y a une erreur : la somme des pourcentages vaut ${S} %, pas 100 %.`;
