      const n = eff.reduce((a, b) => a + b, 0), s = vals.reduce((a, v, i) => a + v * eff[i], 0), m = s / n, ok = Math.abs(m * 10 - Math.round(m * 10)) < 1e-9;
      const tab = `| Note | ${vals.map(v => `$${v}$`).join(' | ')} |\n|:-:|${vals.map(() => ':-:').join('|')}|\n| Effectif | ${eff.map(v => `$${v}$`).join(' | ')} |`;
