      const FR = (a, b) => { const [p, q] = this.simplifyFraction(a, b); return q === 1 ? String(p) : `${p}/${q}`; };
      let txt, test, near = null, m = 0, s = 0;
      if (ty === 'face') { s = R(1, n); txt = `obtenir la face $${s}$`; test = x => x === s; }
